AGENT_NODE_ARCHIVE
printf '%s  %s\n' 'abe65bec7d4cb4375aebe044f79beed8a43fd032a965fd7435ba676d1ac8258d' "$staging/project.tar.gz" | sha256sum --check --status
mkdir -m700 "$staging/project"
tar -xzf "$staging/project.tar.gz" -C "$staging/project"
[[ -f "$staging/project/install.sh" && -f "$staging/project/linux/setup.sh" ]] || { echo '安装包不完整。' >&2; exit 1; }
if [[ -d "$target" ]]; then
  previous="$(mktemp -d "$install_parent/agent-node-backup.XXXXXX")"
  mv -T "$target" "$previous/project"
  echo "旧程序备份：$previous/project"
fi
mv -Tn "$staging/project" "$target"
[[ ! -d "$staging/project" ]] || { echo '目标目录已被其他进程创建；未覆盖。' >&2; exit 1; }
if [[ "$toolkit_only" == yes ]]; then
  echo '部署工具包已更新；未安装依赖或重启服务。请重新输入 openhands 打开新菜单。'
else
  bash "$target/install.sh" "${role_args[@]}" "$@"
fi
finished=1
